def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    noise = {0, 5, 8, 9}
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in noise or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            boxes.append((color, min(y for y, x in cells),
                          max(y for y, x in cells),
                          min(x for y, x in cells),
                          max(x for y, x in cells)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] in noise:
                out[r][c] = bg

    for color, r0, r1, c0, c1 in boxes:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
